begin;
\ir _harness.psql

select plan(28);

select tests.create_household('a') as a, tests.create_household('b') as b, tests.create_household('c') as c \gset

-- Household a, on the database clock's 2026-10-07: lease T billed by calendar month from 01/08 at 3.000.000 ₫, collected
-- to 30/09 before Esta; Thủ Đức's lease R to 01/11 at 9.000.000 ₫; and draft V with invoices written by hand, one issued,
-- one void and one shortened by a paid-through date.
select set_config('esta.actor', 'system:test', true);
   '00000000-0000-4000-8000-00000000a5a1', '2026-08-01', '2027-07-31', 3000000, 'calendar_month'),
  ('00000000-0000-4000-8000-00000000e5a3', :'a', '00000000-0000-4000-8000-0000000005a3', private.whole_unit_id('00000000-0000-4000-8000-0000000005a3'),
   '00000000-0000-4000-8000-00000000a5a1', '2025-11-01', '2026-11-01', 9000000, 'calendar_month'),
  ('00000000-0000-4000-8000-00000000e5a4', :'a', '00000000-0000-4000-8000-0000000005a4', private.whole_unit_id('00000000-0000-4000-8000-0000000005a4'),
   '00000000-0000-4000-8000-00000000a5a1', '2026-01-01', null, 5000000, 'calendar_month');

  on conflict (id) do update set frozen_now = excluded.frozen_now;

-- Golden vectors: every call main's TypeScript planner (packages/core/src/schedule/generate.ts and
-- lease/invoicing.ts at 33c5823) made in its unit tests, the /dev/core examples, 160 fast-check samples from its property
-- tests with amendments placed on the period grid, the activation preview and amendment grids of
-- leases.integration.test.ts and the nightly grid of cron.integration.test.ts, each with the rows it returned. Those files
-- and their parity harness were deleted in #195; the database is now the one planner and must keep planning these rows.
-- Left out: a due offset below 0 and an end date before the start, which the leases table refuses, and planInvoices'
-- meter readings, which arrive with P3-14.

create temporary table schedule_case (
  case_id integer primary key, name text not null, start_date date, end_date date, rent_vnd bigint, cycle smallint, anchor text,
  proration text, due_offset smallint, escalation jsonb, paid_through date, utilities text, until date,
  lease_id uuid not null default gen_random_uuid()
) on commit drop;
create temporary table schedule_amendment (case_id integer, effective_period_start date, changes jsonb) on commit drop;
create temporary table schedule_expected (
  case_id integer, period_start date, period_end date, due_date date, cycle_months integer, monthly_rent_vnd bigint, rent_vnd bigint,
  prorated boolean, covered_by_paid_through boolean
) on commit drop;

create temporary table plan_case (
  case_id integer primary key, name text not null, start_date date, end_date date, rent_vnd bigint, cycle smallint, anchor text,
  proration text, due_offset smallint, escalation jsonb, paid_through date, utilities text, as_of date,
  lease_id uuid not null default gen_random_uuid()
) on commit drop;
create temporary table plan_amendment (case_id integer, effective_period_start date, changes jsonb) on commit drop;
create temporary table plan_expected (case_id integer, period_start date, period_end date, due_date date, issue_on date, rent_vnd bigint) on commit drop;

create temporary table cron_case (
  case_id integer primary key, name text not null, start_date date, end_date date, rent_vnd bigint, cycle smallint, anchor text,
  proration text, due_offset smallint, escalation jsonb, paid_through date, utilities text,
  lease_id uuid not null default gen_random_uuid()
) on commit drop;
create temporary table cron_expected (case_id integer, period_start date, period_end date, due_date date, issue_on date, status text, rent_vnd bigint) on commit drop;

create temporary table months_expected (from_date date, to_date date, months integer) on commit drop;

  id, household_id, property_id, unit_id, start_date, end_date, rent_vnd, billing_cycle_months, period_anchor, first_period_proration,
  due_offset_days, escalation, paid_through_date, utilities_mode
)
select lease_id, :'a', '00000000-0000-4000-8000-0000000005a1', private.whole_unit_id('00000000-0000-4000-8000-0000000005a1'), start_date,
  end_date, rent_vnd, cycle, anchor, proration, due_offset, escalation, paid_through, utilities
from (select lease_id, start_date, end_date, rent_vnd, cycle, anchor, proration, due_offset, escalation, paid_through, utilities from schedule_case
      union all
      select lease_id, start_date, end_date, rent_vnd, cycle, anchor, proration, due_offset, escalation, paid_through, utilities from plan_case) golden;
select :'a', c.lease_id, a.effective_period_start, a.changes from schedule_amendment a join schedule_case c using (case_id)
union all
select :'a', c.lease_id, a.effective_period_start, a.changes from plan_amendment a join plan_case c using (case_id);
  id, household_id, property_id, unit_id, tenant_party_id, start_date, end_date, rent_vnd, billing_cycle_months, period_anchor,
  first_period_proration, due_offset_days, escalation, paid_through_date, utilities_mode, status
)
select lease_id, :'c', '00000000-0000-4000-8000-0000000005c1', private.whole_unit_id('00000000-0000-4000-8000-0000000005c1'),
  '00000000-0000-4000-8000-00000000a5c1', start_date, end_date, rent_vnd, cycle, anchor, proration, due_offset, escalation, paid_through,
  utilities, 'active'
from cron_case;
grant select on schedule_case, schedule_expected to authenticated;

select is((select count(*)::integer from schedule_case), 257, 'every golden schedule case is here');
select is((select count(*)::integer from schedule_expected), 1450, 'every golden schedule period is here');
select is((select count(*)::integer from plan_case), 88, 'every golden billing plan is here');
select is((select count(*)::integer from cron_case), 72, 'every golden nightly lease is here');
select is((select count(*)::integer from months_expected), 208, 'every golden month count is here');

-- LSE-3: cycles of 1, 3, 6 and 12 months, both anchors, proration, increases with rounding, paid-through dates, end dates
-- mid-cycle and amendments, read through the guarded function as a viewer.
select tests.act_as('viewer.a@test.esta.test');
select is_empty(
  $$ with actual as (
       select c.case_id, s.period_start, s.period_end, s.due_date, s.cycle_months, s.monthly_rent_vnd, s.rent_vnd, s.prorated, s.covered_by_paid_through
       from schedule_case c cross join lateral public.lease_schedule(array[c.lease_id], c.until) s
     )
     select c.name, d.period_start
     from ((select * from actual except select * from schedule_expected) union all (select * from schedule_expected except select * from actual)) d
     join schedule_case c using (case_id) $$,
  'lease_schedule plans every golden lease exactly as the TypeScript planner did');
select is(
  (select count(*)::integer from public.lease_schedule((select array_agg(lease_id) from schedule_case), '2026-10-07')),
  (select count(*)::integer from schedule_case c cross join lateral public.lease_schedule(array[c.lease_id], '2026-10-07')),
  'many leases in one call return the same periods as one call each');
select tests.clear_request();
reset role;

-- The billing plan on top of the schedule: paid-through remainders, the 35-day horizon, issue days and amendments.
select is_empty(
  $$ with actual as (
       select c.case_id, p.period_start, p.period_end, p.due_date, p.issue_on, p.rent_vnd
       from plan_case c join public.leases l on l.id = c.lease_id cross join lateral private.plan_invoices(l, c.as_of) p
     )
     select c.name, d.period_start
     from ((select * from actual except select * from plan_expected) union all (select * from plan_expected except select * from actual)) d
     join plan_case c using (case_id) $$,
  'plan_invoices plans every golden lease exactly as planInvoices did');

-- §5.4 and §7.4: six nights of the daily job write exactly what the golden nightly model wrote, skipping every stretch
-- already billed.
select is(
  (select sum(r.drafted)::integer from (values ('2026-10-07'::date), ('2026-11-02'), ('2026-12-31'), ('2027-02-01'), ('2027-04-20'), ('2027-05-02')) n (night)
   cross join lateral public.run_invoicing(:'c', n.night, (n.night + time '00:30') at time zone 'Asia/Ho_Chi_Minh') r),
  281,
  'the nightly job drafts 281 invoices for the golden leases over six nights');
select is_empty(
  $$ with actual as (
       select c.case_id, i.period_start, i.period_end, i.due_date, i.issue_on, i.status, sum(l.amount_vnd)::bigint as rent_vnd
       from cron_case c join public.invoices i on i.lease_id = c.lease_id join public.invoice_lines l on l.invoice_id = i.id
       group by c.case_id, i.id
     )
     select c.name, d.period_start
     from ((select * from actual except select * from cron_expected) union all (select * from cron_expected except select * from actual)) d
     join cron_case c using (case_id) $$,
  'run_invoicing writes, night by night, exactly the golden invoices');

select is_empty(
  $$ select from_date, to_date from months_expected where private.months_until(from_date, to_date) <> months $$,
  'months_until counts whole months as the golden cases do');

-- The invoice beside each period: the live one whose start falls in it, never a void one.
select tests.act_as('viewer.a@test.esta.test');
select results_eq(
  $$ select period_start, invoice_id, invoice_status from public.lease_schedule(array['00000000-0000-4000-8000-00000000e5a4'::uuid], '2026-04-30') $$,
  $$ values ('2026-01-01'::date, '00000000-0000-4000-8000-0000000f05a1'::uuid, 'issued'::text), ('2026-02-01', null, null),
            ('2026-03-01', '00000000-0000-4000-8000-0000000f05a3', 'draft'), ('2026-04-01', null, null) $$,
  'each period names the live invoice that bills it, a shortened one included, and skips a void one');
select tests.clear_request();
reset role;

-- LSE-2 through the member functions: activation, termination and renewal on the database clock.
select tests.act_as('member.a@test.esta.test');
select lives_ok($$ select public.activate_lease('00000000-0000-4000-8000-00000000e5a2', '2026-09-30') $$, 'lease T activates paid through 30/09');
select results_eq(
  $$ select period_start, period_end, rent_vnd, covered_by_paid_through, invoice_status from public.lease_schedule(array['00000000-0000-4000-8000-00000000e5a2'::uuid], '2026-12-31') $$,
  $$ values ('2026-08-01'::date, '2026-08-31'::date, 3000000::bigint, true, null::text), ('2026-09-01', '2026-09-30', 3000000, true, null),
            ('2026-10-01', '2026-10-31', 3000000, false, 'issued'), ('2026-11-01', '2026-11-30', 3000000, false, 'draft'),
            ('2026-12-01', '2026-12-31', 3000000, false, null) $$,
  'an active lease shows its prepaid, issued, drafted and future periods');
select lives_ok($$ select public.terminate_lease('00000000-0000-4000-8000-00000000e5a2', '2026-11-15', 'Trả mặt bằng sớm Demo') $$, 'lease T terminates on 15/11');
select results_eq(
  $$ select period_start, period_end, rent_vnd, prorated, invoice_status from public.lease_schedule(array['00000000-0000-4000-8000-00000000e5a2'::uuid], '2026-12-31')
     where period_start >= '2026-10-01' $$,
  $$ values ('2026-10-01'::date, '2026-10-31'::date, 3000000::bigint, false, 'issued'::text), ('2026-11-01', '2026-11-15', 1500000, true, 'draft') $$,
  'a terminated lease ends at its termination date, prorating the last period by days');
select lives_ok($$ select public.activate_lease('00000000-0000-4000-8000-00000000e5a3', '2026-09-30') $$, 'Thủ Đức activates paid through 30/09');
select lives_ok($$ select public.renew_lease('00000000-0000-4000-8000-00000000e5a3', 500, '2027-10-31') $$, 'Thủ Đức renews 5% up');
select results_eq(
  $$ select period_start, period_end, monthly_rent_vnd, rent_vnd, prorated from public.lease_schedule(
       array(select id from public.leases where id = '00000000-0000-4000-8000-00000000e5a3' or renewal_of_lease_id = '00000000-0000-4000-8000-00000000e5a3'), '2027-01-31')
     where period_start >= '2026-10-01' order by period_start $$,
  $$ values ('2026-10-01'::date, '2026-10-31'::date, 9000000::bigint, 9000000::bigint, false), ('2026-11-01', '2026-11-01', 9000000, 300000, true),
            ('2026-11-02', '2026-11-30', 9500000, 9183333, true), ('2026-12-01', '2026-12-31', 9500000, 9500000, false),
            ('2027-01-01', '2027-01-31', 9500000, 9500000, false) $$,
  'a renewal plans from the day after the old lease ends at the increased rent, and the old lease keeps its one-day period');
select tests.clear_request();
reset role;

-- Membership: a member of another household reads no period, and only signed-in members may call the function.
select tests.act_as('admin.b@test.esta.test');
select is_empty(
  $$ select 1 from public.lease_schedule(array['00000000-0000-4000-8000-00000000e5a2'::uuid, '00000000-0000-4000-8000-00000000e5a4'], '2026-12-31') $$,
  'a member of another household reads no period of household a');
select tests.clear_request();
reset role;
select ok(not has_function_privilege('anon', 'public.lease_schedule(uuid[], date)', 'execute'), 'anon cannot call lease_schedule');
select ok(has_function_privilege('authenticated', 'public.lease_schedule(uuid[], date)', 'execute'), 'a signed-in member can call lease_schedule');
select ok(not has_function_privilege('authenticated', 'private.issue_invoice(uuid, date, timestamptz)', 'execute'), 'a member cannot issue one draft directly');
select ok(not has_function_privilege('service_role', 'private.issue_invoice(uuid, date, timestamptz)', 'execute'), 'nor can the service role');

-- One draft issues on a chosen day: the path a manual issue and P3-14's readings trigger share, and the seed's stand-in for
-- Dĩ An's meter entry on 03/10.
select lives_ok(
  $$ select private.issue_invoice('00000000-0000-4000-8000-0000000f05a3', '2026-03-05', '2026-03-05T10:00:00+07:00') $$,
  'issue_invoice issues a draft');
select results_eq(
  $$ select status, issue_on, issued_at from public.invoices where id = '00000000-0000-4000-8000-0000000f05a3' $$,
  $$ values ('issued'::text, '2026-03-05'::date, '2026-03-05T10:00:00+07:00'::timestamptz) $$,
  'the draft is issued on that day, at that instant');
select throws_ok(
  $$ select private.issue_invoice('00000000-0000-4000-8000-0000000f05a3', '2026-03-06', '2026-03-06T10:00:00+07:00') $$,
  '55000', 'ESTA_INVOICE_NOT_DRAFT', 'an issued invoice cannot issue again');
select throws_ok(
  $$ select private.issue_invoice('00000000-0000-4000-8000-0000000f05a1', null, '2026-03-06T10:00:00+07:00') $$,
  '22004', 'ESTA_ISSUE_ARGUMENTS', 'the day is required');

select * from finish();
rollback;
